    15→    public function project()
    16→    {
    17→        return $this->belongsTo(Project::class);
    18→    }
    19→
    20→    // Flujo de estados en orden
    21→    const STATUS_FLOW = ['backlog', 'en_progreso', 'testing', 'terminada'];
    22→
    23→    public function nextStatus(): ?string
    24→    {
    25→        $idx = array_search($this->status, self::STATUS_FLOW);
    26→        return self::STATUS_FLOW[$idx + 1] ?? null;
    27→    }
    28→
    29→    public function isFinished(): bool
    30→    {
    31→        return $this->status === 'terminada';
    32→    }
    33→}
