<script>
// Activar tab según hash de la URL y sincronizar sidebar
(function () {
    const hash = window.location.hash;
    if (hash === '#pane-historial') {
        const tabEl = document.getElementById('tab-historial');
        if (tabEl) bootstrap.Tab.getOrCreateInstance(tabEl).show();
    }

    // Marcar activo en el sidebar el link de historial si ese tab está visible
    document.querySelectorAll('#projectTabs [data-bs-toggle="tab"]').forEach(function (tabEl) {
        tabEl.addEventListener('shown.bs.tab', function (e) {
            const sidebarLink = document.getElementById('sidebar-historial-link');
            if (!sidebarLink) return;
            if (e.target.id === 'tab-historial') {
                sidebarLink.classList.add('active');
            } else {
                sidebarLink.classList.remove('active');
            }
        });
    });

    // Estado inicial del sidebar según hash
    if (hash === '#pane-historial') {
        const sidebarLink = document.getElementById('sidebar-historial-link');
        if (sidebarLink) sidebarLink.classList.add('active');
    }
})();
</script>

