<script>
(function () {
    const modal = document.getElementById('exportModal');
    if (!modal) return;

    // Captura los datos en el click, ANTES de que el dropdown se cierre
    // y se pierda la referencia al elemento (relatedTarget puede ser null
    // cuando el trigger vive dentro de un dropdown de Bootstrap)
    let pending = {};

    document.querySelectorAll('[data-bs-target="#exportModal"]').forEach(function (el) {
        el.addEventListener('click', function () {
            pending = {
                excelUrl:    this.dataset.excelUrl,
                csvUrl:      this.dataset.csvUrl,
                projectName: this.dataset.projectName,
            };
        });
    });

    modal.addEventListener('show.bs.modal', function () {
        document.getElementById('exportExcelBtn').href            = pending.excelUrl  || '#';
        document.getElementById('exportCsvBtn').href              = pending.csvUrl    || '#';
        document.getElementById('exportModalProject').textContent = pending.projectName || '';
    });
})();
</script>

